    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(ActoAdministrativoPeer::DATABASE_NAME);
        }

        ActoAdministrativoPeer::addSelectColumns($criteria);
        $startcol = ActoAdministrativoPeer::NUM_HYDRATE_COLUMNS;
        DependenciaPeer::addSelectColumns($criteria);

        $criteria->addJoin(ActoAdministrativoPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseActoAdministrativoPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ActoAdministrativoPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ActoAdministrativoPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = ActoAdministrativoPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ActoAdministrativoPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = DependenciaPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = DependenciaPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = DependenciaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    DependenciaPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (ActoAdministrativo) to $obj2 (Dependencia)
                $obj2->addActoAdministrativo($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


