     *
     * @param int $pk the primary key.
     * @param      PropelPDO $con the connection to use
     * @return ActoAdministrativo
     */
    public static function retrieveByPK($pk, PropelPDO $con = null)
    {

        if (null !== ($obj = ActoAdministrativoPeer::getInstanceFromPool((string) $pk))) {
            return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(ActoAdministrativoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria = new Criteria(ActoAdministrativoPeer::DATABASE_NAME);
        $criteria->add(ActoAdministrativoPeer::ACTOADMINISTRATIVO_ID, $pk);

        $v = ActoAdministrativoPeer::doSelect($criteria, $con);

        return !empty($v) > 0 ? $v[0] : null;
    }

