    public static function retrieveByPKs($pks, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ActoAdministrativoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $objs = null;
